mapper.select:
SELECT m.merchant_id, m.merchant_name, mb.brand_name, mc.category_code, mc.category_name, m.address, m.latitude, m.longitude, ROUND( 6371000 * 2 * ASIN(SQRT( POWER(SIN(RADIANS(m.latitude - #{latitude}) / 2), 2) + COS(RADIANS(#{latitude})) * COS(RADIANS(m.latitude)) * POWER(SIN(RADIANS(m.longitude - #{longitude}) / 2), 2) )), 0 ) AS distance_meters, CAST(4.6 AS DECIMAL(2,1)) AS rating, EXISTS ( SELECT 1 FROM bookmarked_stores bs WHERE bs.user_id = #{userId} AND bs.merchant_id = m.merchant_id AND bs.is_deleted = FALSE ) AS bookmarked, uc.user_card_id, c.card_id, c.card_name, c.card_image_url, NULL AS benefit_id, COALESCE( JSON_UNQUOTE(JSON_EXTRACT(c.benefits_info, '$.discountMethod')), JSON_UNQUOTE(JSON_EXTRACT(c.benefits_info, '$.benefitType')) ) AS benefit_type, COALESCE( JSON_UNQUOTE(JSON_EXTRACT(c.benefits_info, '$.categoryName')), c.card_name ) AS benefit_name, COALESCE( JSON_UNQUOTE(JSON_EXTRACT(c.benefits_info, '$.description')), c.description ) AS benefit_description, c.benefits_info FROM merchants m JOIN merchant_categories mc ON mc.category_id = m.category_id LEFT JOIN merchant_brands mb ON mb.brand_id = m.brand_id JOIN user_cards uc ON uc.user_id = #{userId} JOIN cards c ON c.card_id = uc.card_id WHERE uc.status = 'ACTIVE' AND uc.recommendation_enabled = TRUE AND c.is_supported = TRUE AND c.benefits_info IS NOT NULL
AND mc.category_code = #{categoryCode}
HAVING distance_meters <= #{radiusMeters} ORDER BY distance_meters ASC LIMIT #{candidateLimit}
